def specialFilter(nums):
    def is_odd_digit(d):
        return d in {1, 3, 5, 7, 9}

    count = 0
    for num in nums:
        abs_num = abs(num)
        first_digit = abs_num // 10
        last_digit = abs_num % 10

        if num > 10 and is_odd_digit(first_digit) and is_odd_digit(last_digit):
            count += 1
    return count
